-- DESTINO EXCLUSIVO: mayalex-ia-pinel-hn (producción) (thgrhueckkjdutjvcufp). El ejecutor verifica el project ref y la huella SHA-256 de este archivo antes de correrlo.
-- Activa V5 atómicamente (124 filas: 124 PRIMARY, 0 CONTEXT) y oculta las 124 filas legacy sustituidas (legacy HN_LEY_JUSTICIA_CONSTITUCIONAL (V2), ids v2ljc:mayalex_normativos:*).

BEGIN;
DO $do$ DECLARE n int; BEGIN
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA12_LJC_2007_01' AND metadata->>'norm_id' = 'HN:LEY_JUSTICIA_CONSTITUCIONAL'
    AND instrumento_id = 'LEY_JUSTICIA_CONSTITUCIONAL' AND jurisdiccion = 'HN' AND encode(sha256(convert_to(contenido, 'UTF8')), 'hex') = hash_contenido AND revision_pendiente = true AND es_norma_vigente IS NULL AND embedding IS NOT NULL AND embedding <> array_fill(0::real, ARRAY[384])::vector;
  IF n <> 124 THEN RAISE EXCEPTION 'precondición V5: % filas (esperadas 124)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA12_LJC_2007_01';
  IF n <> 124 THEN RAISE EXCEPTION 'filas extra en el lote: % (esperadas 124)', n; END IF;
  UPDATE public.biblioteca_vectores SET revision_pendiente = false, es_norma_vigente = true,
    metadata = (metadata - 'rol' - 'clasificacion_propuesta') || jsonb_build_object('estado_v', 'V5', 'vigencia', 'TRUE_PRESUNTA', 'revision_pendiente', false, 'motivo_rol', 'PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)', 'adjudicacion', 'EXPEDIENTE_AUDITORIA_LJC_OLA12.md (D1–D8)', 'promocion_fecha', '2026-11-24', 'promocion_ola', 'OLA12')
